    private GoliathGrid() {
    }

    public static int square(int x, int z) {
        return x < 0 || z < 0 || x >= 36 || z >= 36 ? -1 : CELLS[z][x];
    }

    public static int at(double x, double z) {
        int gx = (int)Math.floor((x + 225000.0) / 12500.0);
        int gz = (int)Math.floor((z + 225000.0) / 12500.0);
        return GoliathGrid.square(gx, gz);
    }

    public static double centerX(int x) {
        return -225000.0 + ((double)x + 0.5) * 12500.0;
    }

    public static double centerZ(int z) {
        return -225000.0 + ((double)z + 0.5) * 12500.0;
    }

    public static int[] bounds(int code) {
        int[] nArray;
        if (code < 0) {
            return null;
        }
        int u0 = 36;
        int v0 = 36;
        int u1 = -1;
        int v1 = -1;
        for (int z = 0; z < 36; ++z) {
            for (int x = 0; x < 36; ++x) {
                if (CELLS[z][x] != code) continue;
                u0 = Math.min(u0, x);
                v0 = Math.min(v0, z);
                u1 = Math.max(u1, x + 1);
                v1 = Math.max(v1, z + 1);
            }
        }
        if (u1 < 0) {
            nArray = null;
        } else {
            int[] nArray2 = new int[4];
            nArray2[0] = u0;
            nArray2[1] = v0;
            nArray2[2] = u1;
            nArray = nArray2;
            nArray2[3] = v1;
        }
        return nArray;
    }

    public static String label(int code) {
        if (code < 0) {
            return "Off the map";
        }
        int region = code / 1000;
        if (region < 0 || region >= REGIONS.length) {
            return "Goliath " + code;
        }
        return REGIONS[region] + " " + (code % 1000 + 1);
    }

    public static double[] blockArea(int code) {
        int[] b = GoliathGrid.bounds(code);
        if (b == null) {
            return null;
        }
        return new double[]{-225000.0 + (double)b[0] * 12500.0, -225000.0 + (double)b[1] * 12500.0, -225000.0 + (double)b[2] * 12500.0, -225000.0 + (double)b[3] * 12500.0};
    }

    public static int region(int code) {
        int r = code / 1000;
        return code < 0 || r < 0 || r >= REGIONS.length ? -1 : r;
    }

    public static int cells(int code) {
        int[] b = bounds(code);
        return b == null ? 0 : (b[2] - b[0]) * (b[3] - b[1]);
    }

    public static double[] edges(int code, double x, double z) {
        double[] a = blockArea(code);
        return a == null ? null : new double[]{x - a[0], a[2] - x, z - a[1], a[3] - z};
    }

    public static int[] neighbours(int code) {
        int[] b = bounds(code);
        if (b == null) return new int[0];
        java.util.LinkedHashSet<Integer> out = new java.util.LinkedHashSet<>();
        for (int z = b[1] - 1; z <= b[3]; z++) {
            for (int x = b[0] - 1; x <= b[2]; x++) {
                if (x >= b[0] && x < b[2] && z >= b[1] && z < b[3]) continue;
                int c = square(x, z);
                if (c >= 0 && c != code) out.add(c);
            }
        }
        int[] r = new int[out.size()];
        int i = 0;
        for (int c : out) r[i++] = c;
        return r;
    }

    public static int[] inRegion(int region) {
        java.util.TreeSet<Integer> out = new java.util.TreeSet<>();
        for (int z = 0; z < GRID; z++) {
            for (int x = 0; x < GRID; x++) {
                if (CELLS[z][x] / 1000 == region) out.add(CELLS[z][x]);
            }
        }
        int[] r = new int[out.size()];
        int i = 0;
        for (int c : out) r[i++] = c;
        return r;
    }
